#include <iostream>
#include <vector>
using namespace std;

// 计算方案数
long long solve(int n) {
    // 标记完全平方数
    vector<bool> isSquare(n + 1, false);
    for (int i = 1; i * i <= n; i++) {
        isSquare[i * i] = true;
    }

    // dp[x] 表示乘积为 x 的合法有序分配方案数
    vector<long long> dp(n + 1, 0);
    dp[1] = 1; // 边界

    // 从小到大刷表
    for (int i = 1; i <= n; i++) {
        if (dp[i] == 0) continue;

        // 枚举下一份大小 j，j 不是完全平方数
        for (int j = 2; j <= n / i; j++) {
            if (!isSquare[j]) {
                dp[i * j] += dp[i];
            }
        }
    }

    return dp[n];
}

int main() {
    int n;
    cin >> n;
    cout << solve(n) << '\n';
    return 0;
}
